<?php
namespace Tests\Feature;
use App\Models\EditorialPitch;use App\Models\EditorialSourceClaim;use App\Models\User;use App\Services\EditorialFactCheckService;use Illuminate\Foundation\Testing\RefreshDatabase;use Spatie\Permission\Models\Role;use Tests\TestCase;
class EditorialVerificationTest extends TestCase{use RefreshDatabase;
 public function test_automatic_analysis_never_confirms_claim():void{$p=EditorialPitch::create(['title'=>'Pauta','status'=>'review','priority'=>'normal']);$s=$p->sources()->create(['title'=>'Fonte','url'=>'https://example.com','reliability'=>'high','excerpt'=>'O evento será em 20/08/2026.']);$c=$s->claims()->create(['editorial_pitch_id'=>$p->id,'claim'=>'O evento será em 20/08/2026','status'=>'review_required']);$this->assertSame('review_required',app(EditorialFactCheckService::class)->automaticStatus($c));}
 public function test_human_review_is_recorded_with_rationale():void{Role::findOrCreate('Jornalista');$u=User::factory()->create();$u->assignRole('Jornalista');$p=EditorialPitch::create(['title'=>'Pauta','status'=>'review','priority'=>'normal']);$s=$p->sources()->create(['title'=>'Fonte','reliability'=>'high']);$c=$s->claims()->create(['editorial_pitch_id'=>$p->id,'claim'=>'Afirmação factual','status'=>'review_required']);$this->actingAs($u)->post("/admin/redacao/verificacao/afirmacoes/{$c->id}",['decision'=>'unconfirmed','rationale'=>'A fonte apresentada não contém evidência suficiente.'])->assertRedirect();$this->assertSame('unconfirmed',$c->fresh()->status);$this->assertDatabaseHas('editorial_verification_reviews',['editorial_source_claim_id'=>$c->id,'reviewed_by'=>$u->id]);}
}
